package alphametics

import (
	"errors"
	"strings"
)

func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	addends := strings.Split(eq[0], "+")
	for i := range addends {
		addends[i] = strings.TrimSpace(addends[i])
	}
	result := strings.TrimSpace(eq[1])

	terms := append(append([]string{}, addends...), result)

	// collect letters
	letterSet := map[rune]bool{}
	leading := map[rune]bool{}
	for _, t := range terms {
		if len(t) > 1 {
			leading[t[0]] = true
		}
		for _, r := range t {
			letterSet[r] = true
		}
	}
	letters := make([]rune, 0, len(letterSet))
	for r := range letterSet {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, errors.New("unsolvable: more than 10 distinct letters")
	}

	// column-wise backtracking
	// terms as []string, result is last
	digit := make(map[rune]int, len(letters))
	used := make([]bool, 10)

	var solve func(col int, carry int) bool
	solve = func(col int, carry int) bool {
		if col == -1 {
			return carry == 0
		}
		// gather distinct letters in this column
		colLetters := map[rune]bool{}
		for _, t := range terms {
			if col < len(t) {
				colLetters[t[len(t)-1-col]] = true
			}
		}
		unassigned := []rune{}
		for r := range colLetters {
			if _, ok := digit[r]; !ok {
				unassigned = append(unassigned, r)
			}
		}
		var assign func(i int) bool
		assign = func(i int) bool {
			if i == len(unassigned) {
				// check column equation
				sum := carry
				for _, t := range addends {
					if col < len(t) {
						sum += digit[t[len(t)-1-col]]
					}
				}
				if col >= len(result) {
					return sum == 0 // no result digit: sum must be 0? Actually if result has no digit in this column, sum must be 0 and carry must be 0... but sum==0 means carry becomes 0
				}
				res := digit[result[len(result)-1-col]]
				return sum%10 == res && (sum/10) >= 0 // carry propagates
				// Actually: sum%10 == res, newCarry = sum/10. Always true for non-negative.
			}
			r := unassigned[i]
			for d := 0; d < 10; d++ {
				if used[d] {
					continue
				}
				if leading[r] && d == 0 {
					continue
				}
				digit[r] = d
				used[d] = true
				if assign(i + 1) {
					return true
				}
				delete(digit, r)
				used[d] = false
			}
			return false
		}
		return assign(0)
	}

	if solve(0, 0) {
		out := make(map[string]int, len(letters))
		for r, d := range digit {
			out[string(r)] = d
		}
		return out, nil
	}
	return nil, errors.New("no solution found")
}
```

Wait — edge case: if col >= len(result) and sum != 0, then there's a carry into a nonexistent result digit — invalid. sum == 0 is required. And when col >= len(result), the carry must be 0, which is covered by sum == 0.

Also, the "A == B" case: letters A and B, both leading (length 1? "A" has length 1, so not leading). No leading constraint. Column 0: sum of addends = digit(A), result = digit(B). A and B must be different, so no solution → error. Good.

"ACA + DD == BD": A is leading. The solution must not use a leading zero. The spec says a leading-zero solution is invalid → error. Good.

Edge: what if a term is empty after trimming? Not in the test cases. Fine.

Also, the final carry check: after the last column, carry must be 0.

One subtle point: in the column equation check, when col < len(result), sum%10 == res is required. The new carry is sum/10, always ≥ 0. Fine.

Performance: the 199-addend case — 10 letters, column-wise search prunes heavily. The known Exercism Go solution using this approach runs in milliseconds.

