// Solve solves an alphametics puzzle of the form "A + B == C" and returns a
// mapping of each letter to a distinct digit, or an error if no solution exists.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	addends := strings.Split(eq[0], "+")
	for i := range addends {
		addends[i] = strings.TrimSpace(addends[i])
	}
	result := strings.TrimSpace(eq[1])

	terms := append(append([]string{}, addends...), result)

	letterSet := map[rune]bool{}
	leading := map[rune]bool{}
	for _, t := range terms {
		if len(t) > 1 {
			leading[t[0]] = true
		}
		for _, r := range t {
			letterSet[r] = true
		}
	}
	letters := make([]rune, 0, len(letterSet))
	for r := range letterSet {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, errors.New("unsolvable: more than ten distinct letters")
	}

	digit := make(map[rune]int, len(letters))
	used := make([]bool, 10)

	// Column-wise backtracking, rightmost column first.
	var solve func(col int, carry int) bool
	solve = func(col int, carry int) bool {
		if col == -1 {
			return carry == 0
		}
		colLetters := map[rune]bool{}
		for _, t := range terms {
			if col < len(t) {
				colLetters[t[len(t)-1-col]] = true
			}
		}
		unassigned := make([]rune, 0, len(colLetters))
		for r := range colLetters {
			if _, ok := digit[r]; !ok {
				unassigned = append(unassigned, r)
			}
		}
		var assign func(i int) bool
		assign = func(i int) bool {
			if i == len(unassigned) {
				sum := carry
				for _, t := range addends {
					if col < len(t) {
						sum += digit[t[len(t)-1-col]]
					}
				}
				if col >= len(result) {
					return sum == 0 // no result digit here: nothing may carry on
				}
				return sum%10 == digit[result[len(result)-1-col]]
			}
			r := unassigned[i]
			for d := 0; d < 10; d++ {
				if used[d] || (leading[r] && d == 0) {
					continue
				}
				digit[r] = d
				used[d] = true
				if assign(i + 1) {
					return true
				}
				delete(digit, r)
				used[d] = false
			}
			return false
		}
		return assign(0)
	}

	if solve(0, 0) {
		out := make(map[string]int, len(letters))
		for r, d := range digit {
			out[string(r)] = d
		}
		return out, nil
	}
	return nil, errors.New("no solution found")
}

